def v2(n):
    if n == 0: return float('inf')
    c = 0
    while n % 2 == 0:
        n //= 2
        c += 1
    return c

# BFS to compute f(n) = min jumps from 1 to n
from collections import deque

def compute_f(maxN):
    f = {}
    f[1] = 0
    q = deque([1])
    while q:
        n = q.popleft()
        # jump to n+1
        for nxt in [n+1, n + 2**(v2(n)+1)]:
            if nxt <= maxN and nxt not in f:
                f[nxt] = f[n] + 1
                q.append(nxt)
    return f

f = compute_f(2000)

# Print f(2^i) for i=0..10
for i in range(11):
    print(f"f(2^{i}) = {f.get(2**i, 'N/A')}")

print()
# Print f(2^i * k) vs f(2^i) for various i, k
for i in range(7):
    for k in range(2, 6):
        n = 2**i * k
        if n in f:
            print(f"f(2^{i}*{k}) = f({n}) = {f[n]}, f(2^{i}) = {f[2**i]}, diff = {f[n]-f[2**i]}")
    print()
