def v2(n):
    if n == 0: return float('inf')
    c = 0
    while n % 2 == 0:
        n //= 2
        c += 1
    return c

from collections import deque

def compute_f(maxN):
    f = {}
    f[1] = 0
    q = deque([1])
    while q:
        n = q.popleft()
        for nxt in [n+1, n + 2**(v2(n)+1)]:
            if nxt <= maxN and nxt not in f:
                f[nxt] = f[n] + 1
                q.append(nxt)
    return f

f = compute_f(10000)

# Check if f(2^i * k) - f(2^i) is constant in i for fixed odd k
