# Key question: is f(2^i * k) = f(2^i) + f(k) for odd k?
print("Check f(2^i*k) = f(2^i) + f(k) for odd k:")
for k in [3, 5, 7, 9, 11, 13, 15]:
    vals = []
    for i in range(10):
        n = 2**i * k
        if n in f and 2**i in f:
            vals.append((f[n], f[2**i] + f[k], f[n] == f[2**i] + f[k]))
    print(f"  k={k} (f(k)={f[k]}): {vals[:5]}")
